  [ [[v5748eaic9qd3]] ] = { t = [[魔牙术与徒手打击]], q = [=[魔牙术和其他法术对[[徒手打击]]的强化，是作用于全身，还是仅限于身体的某个部位（如拳头或踢击）？]=], a = [=[规则文本写得不够清楚。魔牙术要求施法者选择一项特定的天生武器来强化，因此可以理解为：想强化的每个身体部位（拳、肘、踢、膝、头槌等等）都得各自这样处理一遍。

