  [ [[v5748eaic9vo0]] ] = { t = [[魔法远程武器与弹药]], q = [=[当远程武器把自己的增强加值共享给弹药时，这算“真正的”增强加值，还是更像[[高等魔化武器]]那样的临时加值？换句话说，共享来的增强加值能让箭矢像寒铁、银、精金和阵营属性武器那样绕过伤害减免吗？]=], a = [[不能。除了《核心规则书》指出的那些情形（如果远程武器至少是+1，弹药视为魔法武器；如果远程武器带有阵营属性，弹药同样视为该阵营）之外，远程武器赋予弹药的增强加值并不能帮助弹药克服其他类型的伤害减免。弓手和类似的角色可以购买各种特殊材料的弹药，或增强加值较高的弹药，来克服各种类型的伤害减免。]], book = [[核心规则书]], date = [[2017/01/05]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9vo0]], cat = [[FAQ]], ai = true, pages = { [[魔法物品]] } },
