  [ [[v5748eaic9t7t]] ] = { t = [[秘银盔甲]], q = [[秘银盔甲“在其他限制方面视为轻一类”，这具体是什么意思？]], a = [=[这意味着：当穿戴者自己的职业特性或特殊能力要求她穿着更轻的盔甲时，秘银盔甲也能满足要求；换言之，穿戴这种盔甲的角色受到的限制更少。例如，[[吟游诗人]]穿秘银胸甲施法时没有奥术失败几率；[[野蛮人]]穿秘银全身甲时可以使用快速移动；[[游侠]]穿秘银全身甲时可以使用战斗流派；[[拳师]]、[[游荡剑客]]和[[枪手]]穿秘银胸甲时可以保留机敏加值；[[盗贼]]穿秘银胸甲时保留反射闪避；拳师穿秘银胸甲时可以使用连打；没有[[坚忍]]专长的角色穿秘银胸甲睡觉不会陷入疲乏；等等。这并不改变盔甲实际的类别，也就是说，你仍然可以在带有[[存贮]]的秘银全身甲里存放一只比穿戴者大一个体型类别的生物，而你不能给秘银胸甲添加要求必须是轻甲的特殊能力（如[[喧哗]]），尽管可以添加要求必须是中甲的特殊能力，等等。]=], book = [[核心规则书]], date = [[2015/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9t7t]], cat = [[FAQ]], ai = true, pages = { [[秘银]] } },
  [ [[v5748eaic9naz]] ] = { t = [[武僧疾风连击的BAB]], q = [[武僧的疾风连击写道：“在决定这些攻击时，武僧的基础攻击加值等于其武僧等级。”这与来自职业等级和种族生命骰的BAB如何相互作用？战士19/武僧1进行疾风连击时，BAB是否只算+1？]], a = [[武僧使用疾风连击时，把来自武僧等级的BAB视为等于其武僧等级。他仍然照常把来自其他来源（如其他职业或种族生命骰）的BAB加到这一总值上。

