  [ [[v5748eaic9o72]] ] = { t = [[疾风连击与依BAB而变的专长]], q = [=[武僧进行疾风连击时提升的BAB，如何影响[[猛力攻击]]和[[寓守于攻]]这类效果取决于BAB的专长？]=], a = [[武僧使用疾风连击时提升后的BAB来决定这些专长的效果。]], book = [[核心规则书]], date = [[2011/01/07]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o72]], cat = [[FAQ]], ai = false, pages = { [[武僧]] } },
  [ [[v5748eaic9pyx]] ] = { t = [[武僧疾风连击]], q = [=[使用疾风连击时，我能用同一件武器做出全部攻击，还是必须用两件武器，正如该能力类似[[双武器格斗]]所暗示的那样？]=], a = [=[你可以用同一件武僧武器做出全部攻击。或者，你也可以把其中任意次数的攻击换成[[徒手打击]]。本FAQ明确改变了此前官方博客就这一问题作出的裁定。]=], book = [[核心规则书]], date = [[2012/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9pyx]], cat = [[FAQ]], ai = false, pages = { [[武僧]] } },
  [ [[v5748eaic9qd7]] ] = { t = [[武僧气池与伤害减免]], q = [=[武僧能用气池绕过哪些种类的[[伤害减免]]？]=], a = [[武僧在用徒手打击克服伤害减免时往往很吃力，不得不依靠武器来应对多种伤害减免。我们决定为气池这项职业特性添加一个新能力：7级时，只要气池中还剩至少1点气，武僧的徒手打击在克服伤害减免时视为寒铁和镀银武器。

